'use strict';
const menuButton=document.createElement('button');menuButton.className='mobile-menu-toggle';menuButton.type='button';menuButton.setAttribute('aria-label','Открыть меню');menuButton.setAttribute('aria-expanded','false');menuButton.setAttribute('aria-controls','main-sidebar');menuButton.innerHTML='<svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><path d="M4 6h16M4 12h16M4 18h16"/></svg>';document.querySelector('header').prepend(menuButton);const sidebar=document.querySelector('aside');sidebar.id='main-sidebar';const backdrop=document.createElement('button');backdrop.className='mobile-menu-backdrop';backdrop.type='button';backdrop.setAttribute('aria-label','Закрыть меню');backdrop.tabIndex=-1;backdrop.hidden=true;document.body.append(backdrop);
const menuInertState=new Map();
function syncMenuInert(){if(!document.body.classList.contains('mobile-menu-open'))return;for(const el of [...document.querySelectorAll('body>main'),...document.querySelector('header').children]){if(el===menuButton)continue;if(!menuInertState.has(el))menuInertState.set(el,el.inert);el.inert=true;}}
function toggleMobileMenu(open){document.body.classList.toggle('mobile-menu-open',open);menuButton.setAttribute('aria-expanded',String(open));menuButton.setAttribute('aria-label',open?'Закрыть меню':'Открыть меню');backdrop.hidden=!open;if(open){syncMenuInert();sidebar.querySelector('button:not(:disabled),a[href]')?.focus();}else{for(const [el,value]of menuInertState)el.inert=value;menuInertState.clear();}}
new MutationObserver(syncMenuInert).observe(document.body,{childList:true});
document.addEventListener('keydown',event=>{if(event.key!=='Tab'||!document.body.classList.contains('mobile-menu-open'))return;const targets=[menuButton,...sidebar.querySelectorAll('button:not(:disabled),a[href]')].filter(el=>el.getClientRects().length);const first=targets[0],last=targets[targets.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last||!targets.includes(document.activeElement)){event.preventDefault();first.focus();}});
menuButton.onclick=()=>toggleMobileMenu(!document.body.classList.contains('mobile-menu-open'));backdrop.onclick=()=>toggleMobileMenu(false);sidebar.addEventListener('click',event=>{if(event.target.closest('button:not(:disabled),a'))toggleMobileMenu(false);});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&document.body.classList.contains('mobile-menu-open')){toggleMobileMenu(false);menuButton.focus();}});window.addEventListener('resize',()=>{if(window.innerWidth>700)toggleMobileMenu(false);});
